mapper.select:
select a.*, b.entrust_org_id as entrustOrgId,b.entrust_org_name as entrustOrgName,b.insured_name as insuredName,b.insured_tel as insuredTel,b.insurance_policy_no as insurancePolicyNo, b.hospital_id as hospitalId,b.hospital_name as hospitalName,b.department as department,b.in_hospital_time as inHospitalTime, d.fina_user_name as finaUserName,d.fina_user_tel as finaUserTel from fina_settlement_info a left join fina_applicant_info b on a.fina_info_parent_id = b.id left join fina_applicant_money c on b.id = c.fina_info_id left join fina_applicant d on b.fina_id = d.id where a.delete_flag =0 and b.delete_flag =0
order by a.id desc
limit #{pageIndex}, #{pageSize}

select sum(ifnull(a.submit_services_money,0)) from fina_settlement_info a
where a.id in

  #{item}

